package com.fasterxml.jackson.databind.type;

import com.fasterxml.jackson.databind.JavaType;
import java.io.*;
import java.lang.reflect.Method;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

/**
 * Unit tests for SimpleType._narrow method.
 * Since _narrow is a protected method, we use reflection to access it.
 */
public class SimpleType__narrow_TriageGen0Test {

    @Test
    public void testNarrowSameClassReturnsThis() throws Exception {
        Class<?> clazz = String.class;
        SimpleType type = SimpleType.construct(clazz);

        Method narrowMethod = SimpleType.class.getDeclaredMethod("_narrow", Class.class);
        narrowMethod.setAccessible(true);

        // Act
        JavaType result = (JavaType) narrowMethod.invoke(type, clazz);

        // Assert: If same class, it should return 'this' (identity)
        assertSame("Should return the same instance when class is identical", type, result);
    }

    @Test
    public void testNarrowDifferentClassReturnsNewInstance() throws Exception {
        // Setup: Create a SimpleType for String
        SimpleType type = SimpleType.construct(String.class);

        // Target class: Integer (different from String)
        Class<?> subclass = Integer.class;

        Method narrowMethod = SimpleType.class.getDeclaredMethod("_narrow", Class.class);
        narrowMethod.setAccessible(true);

        // Act
        JavaType result = (JavaType) narrowMethod.invoke(type, subclass);

        // Assert
        assertNotNull("Result should not be null", result);
        assertNotSame("Should return a new instance for a different class", type, result);
        assertTrue("Result should be an instance of SimpleType", result instanceof SimpleType);

        // Check if the new instance has the correct class
        SimpleType resultAsSimpleType = (SimpleType) result;
        // Since we can't access private _class directly via getter easily without more reflection, 
        // we rely on the logic that a new SimpleType is constructed with subclass.
        // We can verify via toString or other side effects if necessary, but standard assertion is:
        assertEquals("The new type should represent the subclass", subclass.getName(), result.toString().split(" ")[0].replace("class ", ""));
    }

    @Test
    public void testNarrowWithSubclassRelationship() throws Exception {
        // Even though the code comments say it doesn't strictly check isAssignableFrom,
        // we test if it handles a subclass relationship correctly.
        SimpleType type = SimpleType.construct(Number.class);
        Class<?> subclass = Integer.class;

        Method narrowMethod = SimpleType.class.getDeclaredMethod("_narrow", Class.class);
        narrowMethod.setAccessible(true);

        // Act
        JavaType result = (JavaType) narrowMethod.invoke(type, subclass);

        // Assert
        assertNotNull(result);
        assertNotSame(type, result);
        assertTrue(result instanceof SimpleType);
    }

    @Test
    public void testNarrowWithUnrelatedClasses() throws Exception {
        // Testing the "no check" behavior mentioned in the comments
        // The code explicitly commented out the isAssignableFrom check.
        SimpleType type = SimpleType.construct(String.class);
        Class<?> unrelated = Double.class;

        Method narrowMethod = SimpleType.class.getDeclaredMethod("_narrow", Class.class);
        narrowMethod.setAccessible(true);

        // Act
        JavaType result = (JavaType) narrowMethod.invoke(type, unrelated);

        // Assert
        assertNotNull(result);
        assertNotSame(type, result);
        // It should successfully return a new SimpleType for Double even though Double is not a subclass of String
        assertTrue(result instanceof SimpleType);
    }
}
